function iconFor(feature:string):React.ComponentProps<typeof Ionicons>['name'] {return ({students:'school-outline',children:'people-outline',users:'person-outline',teachers:'school-outline',employees:'briefcase-outline',classes:'albums-outline',subjects:'book-outline',invoices:'card-outline',payments:'card-outline',surveys:'clipboard-outline',cases:'heart-outline',analytics:'bar-chart-outline',permissions:'shield-outline',archive:'archive-outline',enrollments:'person-add-outline',grades:'ribbon-outline',attendance:'time-outline',assignments:'document-text-outline',lessons:'book-outline',games:'game-controller-outline',curriculum:'library-outline',quran:'bookmarks-outline',library:'library-outline',content:'library-outline',notifications:'notifications-outline'} as Record<string,React.ComponentProps<typeof Ionicons>['name']>)[feature]??'document-outline';}

