     {weakAreas.length?<Surface><SectionHeading title="مهارات تحتاج مراجعة"/>{weakAreas.map((area:AnyRow,index:number)=><View key={`${area.category}-${index}`} style={styles.stat}><Text style={styles.itemDetail}>{area.correct??0} من {area.total??0} · دقة {area.accuracy??0}٪</Text><Text style={styles.itemTitle}>{area.category??'مهارة'}</Text></View>)}</Surface>:null}
